@startuml

class Song {
  + title : string
  + year : int
  + length : double
  + genre : string
}

class Artist {
  + name : string
  + dateOfBirth : date
  + websiteUrl : string
}

class User {
  + id : int
  + name : string
  + address : string
}

class RegularUser {
}

class BusinessUser {
  + vatNumber : string
}

class Single {
}

class Hit {
  + trackNumber : int
}

class Album {
  + title : string
}

class Suggestion {
}

User --|> RegularUser
User --|> BusinessUser

Artist "1" -- "*" Song
BusinessUser "1" -- "*" Song
Single --|> Song
Hit --|> Song

RegularUser "1" -- "*" Single
RegularUser "1" -- "*" Album
Album "1" *-- "1..*" Hit

RegularUser "1" -- "*" Suggestion
RegularUser "1" -- "*" RegularUser : similarBehavior

@enduml

